  "🔔 Tinnitus relief": { es: "🔔 Alivio del acúfeno", ar: "🔔 تخفيف طنين الأذن", zh: "🔔 缓解耳鸣", sw: "🔔 Nafuu ya mlio masikioni", sv: "🔔 Lindring vid tinnitus", de: "🔔 Tinnitus-Linderung", pt: "🔔 Alívio do zumbido", fr: "🔔 Soulager les acouphènes" },
  "🎨 Colours of noise": { es: "🎨 Colores del ruido", ar: "🎨 ألوان الضوضاء", zh: "🎨 噪声的颜色", sw: "🎨 Rangi za kelele", sv: "🎨 Brusets färger", de: "🎨 Farben des Rauschens", pt: "🎨 Cores do ruído", fr: "🎨 Couleurs du bruit" },
  "Each colour spreads its sound differently over low and high notes.": { es: "Cada color reparte su sonido de forma distinta entre notas graves y agudas.", ar: "كل لون يوزّع صوته بشكل مختلف بين النغمات المنخفضة والعالية.", zh: "每种颜色的声音在低音和高音上的分布都不同。", sw: "Kila rangi hueneza sauti yake tofauti kati ya noti za chini na za juu.", sv: "Varje färg fördelar sitt ljud olika över låga och höga toner.", de: "Jede Farbe verteilt ihren Klang anders auf tiefe und hohe Töne.", pt: "Cada cor distribui o som de um jeito diferente entre graves e agudos.", fr: "Chaque couleur répartit son son différemment entre graves et aigus." },
  "What each one does ↓": { es: "Qué hace cada uno ↓", ar: "ماذا يفعل كل منها ↓", zh: "各自的作用 ↓", sw: "Kila moja inafanya nini ↓", sv: "Vad var och en gör ↓", de: "Was jede bewirkt ↓", pt: "O que cada um faz ↓", fr: "Ce que fait chacun ↓" },
  "What it does ↓": { es: "Qué hace ↓", ar: "ماذا يفعل ↓", zh: "有什么作用 ↓", sw: "Inafanya nini ↓", sv: "Vad det gör ↓", de: "Was es bewirkt ↓", pt: "O que faz ↓", fr: "Ce qu’il fait ↓" },
  "White noise": { es: "Ruido blanco", ar: "الضوضاء البيضاء", zh: "白噪声", sw: "Kelele nyeupe", sv: "Vitt brus", de: "Weißes Rauschen", pt: "Ruído branco", fr: "Bruit blanc" },
  "Bright, even hiss — like TV static": { es: "Siseo brillante y uniforme, como la estática de la tele", ar: "هسهسة ساطعة ومتساوية — مثل تشويش التلفاز", zh: "明亮、均匀的嘶嘶声——像电视雪花噪声", sw: "Mzomo mkali na sawa — kama mkwaruzo wa TV", sv: "Ljust, jämnt brus — som tv-brus", de: "Helles, gleichmäßiges Zischen — wie Fernsehrauschen", pt: "Chiado brilhante e uniforme — como estática de TV", fr: "Souffle clair et régulier — comme la neige d’une télé" },
  "Pink noise": { es: "Ruido rosa", ar: "الضوضاء الوردية", zh: "粉红噪声", sw: "Kelele ya waridi", sv: "Rosa brus", de: "Rosa Rauschen", pt: "Ruído rosa", fr: "Bruit rose" },
  "Softer and fuller — like steady rain": { es: "Más suave y lleno, como una lluvia constante", ar: "أنعم وأغنى — مثل مطر متواصل", zh: "更柔和饱满——像持续的雨声", sw: "Laini na kamili zaidi — kama mvua ya kudumu", sv: "Mjukare och fylligare — som jämnt regn", de: "Weicher und voller — wie gleichmäßiger Regen", pt: "Mais suave e cheio — como chuva constante", fr: "Plus doux et plus plein — comme une pluie régulière" },
  "Brown noise": { es: "Ruido marrón", ar: "الضوضاء البنية", zh: "棕噪声", sw: "Kelele ya kahawia", sv: "Brunt brus", de: "Braunes Rauschen", pt: "Ruído marrom", fr: "Bruit brun" },
  "Deep rumble — like a waterfall": { es: "Retumbo profundo, como una cascada", ar: "هدير عميق — مثل شلال", zh: "低沉的轰鸣——像瀑布", sw: "Mngurumo mzito — kama maporomoko ya maji", sv: "Djupt muller — som ett vattenfall", de: "Tiefes Grollen — wie ein Wasserfall", pt: "Ronco profundo — como uma cachoeira", fr: "Grondement profond — comme une cascade" },
  "Blue noise": { es: "Ruido azul", ar: "الضوضاء الزرقاء", zh: "蓝噪声", sw: "Kelele ya buluu", sv: "Blått brus", de: "Blaues Rauschen", pt: "Ruído azul", fr: "Bruit bleu" },
  "Sharp hiss — like a spray of water": { es: "Siseo agudo, como un chorro de agua", ar: "هسهسة حادة — مثل رذاذ الماء", zh: "尖锐的嘶嘶声——像喷水", sw: "Mzomo mkali — kama mnyunyizo wa maji", sv: "Skarpt brus — som en vattenstråle", de: "Scharfes Zischen — wie ein Wasserstrahl", pt: "Chiado agudo — como um jato de água", fr: "Souffle aigu — comme un jet d’eau" },
  "Violet noise": { es: "Ruido violeta", ar: "الضوضاء البنفسجية", zh: "紫噪声", sw: "Kelele ya zambarau", sv: "Violett brus", de: "Violettes Rauschen", pt: "Ruído violeta", fr: "Bruit violet" },
  "Very high, thin hiss": { es: "Siseo muy agudo y fino", ar: "هسهسة عالية جدًا ورفيعة", zh: "非常高而细的嘶嘶声", sw: "Mzomo mwembamba wa juu sana", sv: "Mycket högt, tunt brus", de: "Sehr hohes, dünnes Zischen", pt: "Chiado muito agudo e fino", fr: "Souffle très aigu et fin" },
  "Grey noise": { es: "Ruido gris", ar: "الضوضاء الرمادية", zh: "灰噪声", sw: "Kelele ya kijivu", sv: "Grått brus", de: "Graues Rauschen", pt: "Ruído cinza", fr: "Bruit gris" },
  "Sounds equally loud at every pitch": { es: "Suena igual de fuerte en todos los tonos", ar: "يبدو بالارتفاع نفسه في كل طبقة", zh: "在每个音高上听起来一样响", sw: "Inasikika kwa sauti sawa katika kila kiwango", sv: "Låter lika starkt i alla tonhöjder", de: "Klingt in jeder Tonhöhe gleich laut", pt: "Soa igualmente alto em todos os tons", fr: "Paraît aussi fort à toutes les hauteurs" },
  "Green noise": { es: "Ruido verde", ar: "الضوضاء الخضراء", zh: "绿噪声", sw: "Kelele ya kijani", sv: "Grönt brus", de: "Grünes Rauschen", pt: "Ruído verde", fr: "Bruit vert" },
  "Middle notes only — soft and natural": { es: "Solo notas medias, suave y natural", ar: "النغمات الوسطى فقط — ناعمة وطبيعية", zh: "只有中音——柔和自然", sw: "Noti za kati tu — laini na asilia", sv: "Bara mellantoner — mjukt och naturligt", de: "Nur mittlere Töne — weich und natürlich", pt: "Só tons médios — suave e natural", fr: "Seulement les médiums — doux et naturel" },
  "🌧️ Nature & calm sounds": { es: "🌧️ Sonidos de naturaleza y calma", ar: "🌧️ أصوات الطبيعة والهدوء", zh: "🌧️ 自然与平静的声音", sw: "🌧️ Sauti za asili na utulivu", sv: "🌧️ Natur- och lugna ljud", de: "🌧️ Natur- & Ruheklänge", pt: "🌧️ Sons da natureza e calmos", fr: "🌧️ Sons de nature et de calme" },
  "Made from noise and tiny sound events, so they never loop the same way twice.": { es: "Hechos con ruido y pequeños sonidos, así que nunca se repiten igual.", ar: "مصنوعة من الضوضاء وأحداث صوتية صغيرة، فلا تتكرر بالطريقة نفسها أبدًا.", zh: "由噪声和细小的声音事件组成，所以永远不会以同样方式循环。", sw: "Zimetengenezwa kwa kelele na sauti ndogo ndogo, kwa hiyo hazijirudii kwa njia ile ile kamwe.", sv: "Gjorda av brus och små ljudhändelser, så de upprepas aldrig likadant.", de: "Aus Rauschen und kleinen Klangereignissen gemacht, daher wiederholen sie sich nie gleich.", pt: "Feitos de ruído e pequenos eventos sonoros, então nunca se repetem do mesmo jeito.", fr: "Faits de bruit et de petits événements sonores, ils ne bouclent jamais de la même façon." },
  "Rain": { es: "Lluvia", ar: "المطر", zh: "雨", sw: "Mvua", sv: "Regn", de: "Regen", pt: "Chuva", fr: "Pluie" },
  "Steady rain with drops": { es: "Lluvia constante con gotas", ar: "مطر متواصل مع قطرات", zh: "带雨滴声的持续雨声", sw: "Mvua ya kudumu yenye matone", sv: "Jämnt regn med droppar", de: "Gleichmäßiger Regen mit Tropfen", pt: "Chuva constante com gotas", fr: "Pluie régulière avec des gouttes" },
  "Steady": { es: "Constante", ar: "متواصل", zh: "持续", sw: "Ya kudumu", sv: "Jämnt", de: "Gleichmäßig", pt: "Constante", fr: "Régulière" },
