  "How they work ↓": { es: "Cómo funcionan ↓", ar: "كيف تعمل ↓", zh: "原理 ↓", sw: "Jinsi yanavyofanya kazi ↓", sv: "Hur de fungerar ↓", de: "Wie sie wirken ↓", pt: "Como funcionam ↓", fr: "Comment ça marche ↓" },
