  "A slow beat your brain makes from two tones": { es: "Un pulso lento que tu cerebro crea a partir de dos tonos", ar: "نبضة بطيئة يصنعها دماغك من نغمتين", zh: "大脑由两个音调产生的缓慢节拍", sw: "Mdundo wa polepole ambao ubongo wako hutengeneza kutoka kwa toni mbili", sv: "Ett långsamt slag som hjärnan skapar av två toner", de: "Ein langsamer Beat, den dein Gehirn aus zwei Tönen bildet", pt: "Uma batida lenta que o cérebro cria a partir de dois tons", fr: "Un battement lent que votre cerveau crée à partir de deux sons" },
  "Delta 2 Hz — deep sleep": { es: "Delta 2 Hz: sueño profundo", ar: "دلتا 2 هرتز — نوم عميق", zh: "δ 波 2 Hz——深度睡眠", sw: "Delta 2 Hz — usingizi mzito", sv: "Delta 2 Hz — djup sömn", de: "Delta 2 Hz — Tiefschlaf", pt: "Delta 2 Hz — sono profundo", fr: "Delta 2 Hz — sommeil profond" },
  "Theta 6 Hz — drowsy, dreamy": { es: "Theta 6 Hz: somnoliento, soñador", ar: "ثيتا 6 هرتز — نعاس وأحلام", zh: "θ 波 6 Hz——昏昏欲睡、如梦似幻", sw: "Theta 6 Hz — usingizi mwepesi, ndotoni", sv: "Theta 6 Hz — dåsig, drömmande", de: "Theta 6 Hz — schläfrig, verträumt", pt: "Theta 6 Hz — sonolento, sonhador", fr: "Thêta 6 Hz — somnolent, rêveur" },
  "Alpha 10 Hz — relaxed": { es: "Alfa 10 Hz: relajado", ar: "ألفا 10 هرتز — استرخاء", zh: "α 波 10 Hz——放松", sw: "Alpha 10 Hz — tulivu", sv: "Alfa 10 Hz — avslappnad", de: "Alpha 10 Hz — entspannt", pt: "Alfa 10 Hz — relaxado", fr: "Alpha 10 Hz — détendu" },
